begin;
create function pg_temp.reject_fixture_password_change() returns trigger language plpgsql as $$
begin
 if new.user_id::text=TG_ARGV[0] and current_setting('qa.reject_password',true)='yes' then raise exception using errcode='P0999',message='Falha controlada';end if;
 return new;
end $$;
do $$
declare
 v_org uuid:=gen_random_uuid();v_owner uuid:=gen_random_uuid();v_google uuid:=gen_random_uuid();v_operator uuid:=gen_random_uuid();
 v_email text;v_id uuid:=gen_random_uuid();v_next uuid:=gen_random_uuid();v_hash text:=repeat('a',64);v_hash2 text:=repeat('b',64);
 v_old text:='scrypt$16384$8$1$'||repeat('a',22)||'$'||repeat('a',86);v_new text:='scrypt$16384$8$1$'||repeat('b',22)||'$'||repeat('b',86);
 v_job jsonb;v_lease uuid;v_version text;v_after text;v_trigger text:='qa_password_'||replace(gen_random_uuid()::text,'-','');
begin
 v_email:=v_owner::text||'@fixture.invalid';
 insert into next_auth.users(id,email,name) values(v_owner,v_email,'Dono fixture'),(v_google,v_google::text||'@fixture.invalid','Google fixture'),(v_operator,v_operator::text||'@fixture.invalid','Operação fixture');
 insert into public.organizations(id,name) values(v_org,'Fixture recuperação');
 insert into public.organization_members(organization_id,user_id,role) values(v_org,v_owner,'cliente'),(v_org,v_google,'admin'),(v_org,v_operator,'superadmin');
 insert into app_private.user_password_credentials(user_id,password_hash) values(v_owner,v_old),(v_operator,v_old);
 v_version:=app_private.get_user_session_version(v_owner);
 if v_version='initial' then raise exception 'Credencial nova sem versão';end if;
 update app_private.session_security_enforcement set enabled=true where singleton;
 perform set_config('request.jwt.claim.sub','',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v_owner,'session_version',v_version)::text,true);
 if next_auth.uid() is distinct from v_owner then raise exception 'Sessão atual negada';end if;
 if app_private.start_customer_password_reset(v_id,upper(v_email),v_hash,'{"iv":"fixture","ciphertext":"fixture","tag":"fixture","url":"https://example.invalid/recuperar-senha"}') is distinct from v_id then raise exception 'Não criou solicitação';end if;
 if app_private.get_customer_password_reset_context(v_hash) is not null then raise exception 'Token válido antes do aceite do envio';end if;
 if app_private.start_customer_password_reset(gen_random_uuid(),v_email,v_hash2,'{}') is not null then raise exception 'Ignorou intervalo de reenvio';end if;
 if app_private.start_customer_password_reset(gen_random_uuid(),v_google::text||'@fixture.invalid',repeat('c',64),'{}') is not null then raise exception 'Criou senha Google';end if;
 if app_private.start_customer_password_reset(gen_random_uuid(),v_operator::text||'@fixture.invalid',repeat('d',64),'{}') is not null then raise exception 'Recuperou credencial global';end if;
 if app_private.start_customer_password_reset(gen_random_uuid(),gen_random_uuid()::text||'@fixture.invalid',repeat('e',64),'{}') is not null then raise exception 'Criou conta desconhecida';end if;
 if (select count(*) from app_private.password_reset_deliveries where id=v_id)<>1 then raise exception 'Fila ausente';end if;
 v_job:=app_private.claim_password_reset_delivery(v_id);v_lease:=(v_job->>'leaseId')::uuid;
 if v_job->>'email' is distinct from v_email or app_private.claim_password_reset_delivery(v_id) is not null then raise exception 'Reserva duplicada/destino incorreto';end if;
 begin perform app_private.finish_password_reset_delivery(v_id,gen_random_uuid(),'fixture-message');raise exception 'Lease falso';exception when sqlstate 'PT409' then null;end;
 perform app_private.finish_password_reset_delivery(v_id,v_lease,null,true,120);
 if app_private.claim_password_reset_delivery(v_id) is not null then raise exception 'Ignorou Retry-After';end if;
 update app_private.password_reset_deliveries set available_at=clock_timestamp()-interval '1 second' where id=v_id;
 v_job:=app_private.claim_password_reset_delivery(v_id);v_lease:=(v_job->>'leaseId')::uuid;
 perform app_private.finish_password_reset_delivery(v_id,v_lease,'fixture-message');
 if app_private.get_customer_password_reset_context(v_hash)->>'passwordHash' is distinct from v_old then raise exception 'Não disponibilizou token enviado';end if;
 execute format('create trigger %I before update on app_private.user_password_credentials for each row execute function pg_temp.reject_fixture_password_change(%L)',v_trigger,v_owner::text);
 perform set_config('qa.reject_password','yes',true);
 begin perform app_private.complete_customer_password_reset(v_hash,v_old,v_new);raise exception 'Não injetou falha';exception when sqlstate 'P0999' then null;end;
 if app_private.get_user_session_version(v_owner)<>v_version or app_private.get_customer_password_context(v_owner)->>'passwordHash'<>v_old or app_private.get_customer_password_reset_context(v_hash) is null then raise exception 'Recuperação parcial';end if;
 perform set_config('qa.reject_password','no',true);
 if not app_private.complete_customer_password_reset(v_hash,v_old,v_new) then raise exception 'Não redefiniu senha';end if;
 v_after:=app_private.get_user_session_version(v_owner);
 if v_after=v_version or app_private.get_customer_password_context(v_owner)->>'passwordHash'<>v_new then raise exception 'Senha/sessão não alterada';end if;
 if next_auth.uid() is not null or app_private.is_org_member(v_org) then raise exception 'JWT anterior continuou válido';end if;
 if app_private.complete_customer_password_reset(v_hash,v_new,v_old) then raise exception 'Reutilizou link';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v_owner,'session_version',v_after)::text,true);
 if next_auth.uid() is distinct from v_owner then raise exception 'Sessão nova negada';end if;
 begin perform app_private.change_customer_password(v_owner,v_old,v_new);raise exception 'Ignorou conflito de credencial';exception when sqlstate 'PT409' then null;end;
 for i in 1..5 loop if not app_private.start_customer_password_change(v_owner) then raise exception 'Limite antecipado';end if;end loop;
 if app_private.start_customer_password_change(v_owner) then raise exception 'Ignorou limite de tentativas';end if;
 update app_private.password_reset_requests set created_at=clock_timestamp()-interval '2 minutes' where id=v_id;
 if app_private.start_customer_password_reset(v_next,v_email,v_hash2,'{}') is distinct from v_next then raise exception 'Nova solicitação ausente';end if;
 v_job:=app_private.claim_password_reset_delivery(v_next);v_lease:=(v_job->>'leaseId')::uuid;
 perform app_private.finish_password_reset_delivery(v_next,v_lease,'fixture-message-2');
 update app_private.password_reset_requests set expires_at=clock_timestamp()-interval '1 second' where id=v_next;
 if app_private.get_customer_password_reset_context(v_hash2) is not null then raise exception 'Token expirado aceito';end if;
 update app_private.password_reset_requests set expires_at=clock_timestamp()+interval '1 hour' where id=v_next;
 delete from public.organization_members where organization_id=v_org and user_id=v_owner;
 if next_auth.uid() is not null or app_private.get_customer_password_reset_context(v_hash2) is not null then raise exception 'Acesso removido manteve sessão/recuperação';end if;
 insert into public.organization_members(organization_id,user_id,role) values(v_org,v_owner,'cliente');
 if next_auth.uid() is not null then raise exception 'Reentrada ressuscitou JWT antigo';end if;
 if has_table_privilege('authenticated','app_private.password_reset_requests','select') or has_function_privilege('anon','app_private.complete_customer_password_reset(text,text,text)','execute') then raise exception 'Escopo público indevido';end if;
 perform set_config('request.jwt.claims','{}',true);
 if next_auth.uid() is not null then raise exception 'Anônimo ganhou identidade';end if;
 perform set_config('role','service_role',true);
 perform app_private.get_user_session_version(v_owner);
 perform app_private.get_customer_password_context(v_owner);
end $$;
select 'customer_password_recovery_ok' as result;
rollback;
